def solve(x, weight, bias=None, stride=1, padding=0):
    # x: N,C,H,W; weight: O,C,KH,KW. Numpy-free nested loops.
    N,C,H,W=len(x),len(x[0]),len(x[0][0]),len(x[0][0][0])
    O,_,KH,KW=len(weight),len(weight[0]),len(weight[0][0]),len(weight[0][0][0])
    xp=[[[[0.0]*(W+2*padding) for _ in range(H+2*padding)] for _ in range(C)] for _ in range(N)]
    for n in range(N):
      for c in range(C):
       for i in range(H):
        for j in range(W): xp[n][c][i+padding][j+padding]=x[n][c][i][j]
    OH=(H+2*padding-KH)//stride+1; OW=(W+2*padding-KW)//stride+1
    out=[[[[0.0]*OW for _ in range(OH)] for _ in range(O)] for _ in range(N)]
    for n in range(N):
     for o in range(O):
      for i in range(OH):
       for j in range(OW):
        v=bias[o] if bias is not None else 0.0
        for c in range(C):
         for ki in range(KH):
          for kj in range(KW): v+=xp[n][c][i*stride+ki][j*stride+kj]*weight[o][c][ki][kj]
        out[n][o][i][j]=v
    return out

